INSERT INTO public.profiles (id, email, full_name, role, avatar_url, bio, headline, location) VALUES
('c0000000-0000-0000-0000-000000000001', 'elena@creatorai.io', 'Elena Rostova', 'creator', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'Pioneering cinematic AI direction since 2022. I merge Runway Gen-3 Alpha, Kling AI, and custom ComfyUI diffusion workflows with DaVinci Resolve color grading to produce broadcast-grade AI commercials, film trailers, and high-impact brand spots.', 'Cinematic AI Video Director & Hyperrealistic Worldbuilder', 'Berlin, Germany'),
('c0000000-0000-0000-0000-000000000002', 'marcus@creatorai.io', 'Marcus Chen', 'creator', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'Specializing in persistent virtual influencers and 3D Gaussian Splats. I train bespoke LoRA models and integrate Flux.1 with Blender rigs to deliver photorealistic digital brand ambassadors that maintain exact facial identity across thousands of renders.', 'Generative 3D & Virtual Influencer Architect', 'San Francisco, USA'),
('c0000000-0000-0000-0000-000000000003', 'aria@creatorai.io', 'Aria Vance', 'creator', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=400&q=80', 'Bridging the aesthetics of Vogue and Harper''s Bazaar with high-fidelity generative imagery. I help luxury fashion, cosmetics, and jewelry houses produce international lookbooks and print campaigns.', 'AI Fashion & Luxury Editorial Photography Lead', 'London, UK'),
('c0000000-0000-0000-0000-000000000004', 'kaelen@creatorai.io', 'Kaelen Thorne', 'creator', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80', 'Senior concept artist combining ComfyUI pipelines with 2D paint-over mastery. I create key art, vehicle designs, and sprawling environment matte paintings for indie game studios and film pitch decks.', 'Sci-Fi Concept Artist & Keyframe Worldbuilder', 'Toronto, Canada'),
('c0000000-0000-0000-0000-000000000005', 'sophia@creatorai.io', 'Sophia Martinez', 'creator', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=80', 'Producing high-converting AI UGC (User Generated Content) and dynamic vertical ads for TikTok, Instagram Reels, and YouTube Shorts. I build synthetic video testimonials and trend-focused hooks for DTC brands.', 'AI UGC & Short-Form Video Producer', 'Miami, USA'),
('c0000000-0000-0000-0000-000000000006', 'devon@creatorai.io', 'Devon Brooks', 'creator', 'https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?auto=format&fit=crop&w=400&q=80', 'Creating synthetic sonic identities, multilingual voice cloning, and generative musical scores. I build corporate narration, podcast voices, immersive gaming foley, and brand soundscapes.', 'Synthetic Voice Actor & Generative Soundscape Designer', 'Austin, USA'),
('c0000000-0000-0000-0000-000000000007', 'nia@creatorai.io', 'Nia Patel', 'creator', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&q=80', 'Pioneering zero-shot product staging. I place physical CPG, cosmetics, beverage, and tech products into breathtaking photorealistic environments without studio shoots while preserving exact brand logos.', 'Generative Product Advertising & Packshot Specialist', 'Singapore'),
('c0000000-0000-0000-0000-000000000008', 'liam@creatorai.io', 'Liam O''Connor', 'creator', 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?auto=format&fit=crop&w=400&q=80', 'Pioneering the intersection of generative AI loops, animated brand identities, and dynamic logo reveals. I combine Deforum Stable Diffusion with After Effects and TouchDesigner for hypnotic visual systems.', 'AI Motion Graphics & Generative Brand Identity', 'Dublin, Ireland'),
('b0000000-0000-0000-0000-000000000001', 'brand@apexvolt.com', 'Apex Volt Beverage Co.', 'brand', 'https://images.unsplash.com/photo-1571171637578-41bc2dd41cd2?auto=format&fit=crop&w=200&q=80', 'Next-generation clean energy drink for creatives and esports athletes.', 'Global Energy Beverage Brand', 'New York, USA')
