INSERT INTO public.portfolio_items (creator_id, title, description, category, thumbnail_url, ai_tools, workflow_description, creator_contribution, prompt_snippet, licensing_information) VALUES
('c0000000-0000-0000-0000-000000000001', 'Aetheria - Luxury Perfume Film', 'A 30-second conceptual commercial for an eco-luxury fragrance brand featuring fluid simulation and lighting effects.', 'video', 'https://images.unsplash.com/photo-1592945403244-b3fbafd7f539?auto=format&fit=crop&w=800&q=80', ARRAY['Runway Gen-3', 'Midjourney v6', 'Topaz'], 'Phase 1: Storyboard ideation in Midjourney. Phase 2: High-motion diffusion in Runway Gen-3. Phase 3: Topaz 4K upscaling. Phase 4: DaVinci Resolve color grading.', 'Director & AI Workflow Architect', 'cinematic micro macro shot of iridescent fragrance bottle emerging from bioluminescent smoke, anamorphic 35mm lens --v 6.0', 'Full Commercial Buyout with zero celebrity likeness guarantees.'),
('c0000000-0000-0000-0000-000000000001', 'Neo-Kyoto 2099 Trailer', 'Teaser video clip for a sci-fi streaming series, demonstrating consistent architecture and camera dynamics.', 'video', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&w=800&q=80', ARRAY['Kling AI', 'ComfyUI', 'DaVinci'], 'Camera trajectory locked via Kling AI with custom ControlNet depth guidance.', 'Director & VFX Artist', 'rain-drenched cyberpunk megalopolis, high contrast neon magenta reflections, drone sweeping downward', 'Commercial streaming rights cleared.'),
('c0000000-0000-0000-0000-000000000002', 'Kaiya - AI Virtual Ambassador', 'Created a persistent AI brand ambassador with over 45k Instagram followers for a streetwear label.', 'virtual-influencer', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?auto=format&fit=crop&w=800&q=80', ARRAY['Flux.1 Dev', 'ComfyUI', 'Blender'], 'Trained rank-64 LoRA on Flux.1 for exact bone structure and natural expressions.', 'Character Sculptor & LoRA Trainer', 'portrait of synthetic digital human Kaiya, wearing minimalist streetwear, Tokyo cafe background, skin pores', 'Full IP Assignment including .safetensors LoRA weights.'),
('c0000000-0000-0000-0000-000000000003', 'Solstice - Haute Couture Lookbook', '16-look generative fashion campaign for a London boutique label, printed in physical lookbooks.', 'imagery', 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=800&q=80', ARRAY['Midjourney v6', 'Magnific AI'], 'Passes rendered in Midjourney v6 with Profoto studio tokens, upscaled to 300 DPI via Magnific AI.', 'Creative Director & Prompt Artist', 'high fashion editorial photo, woman in structured golden silk gown, stark desert dunes, Vogue composition', 'Commercial print and billboard rights cleared.'),
('c0000000-0000-0000-0000-000000000004', 'Orbital Citadel - Space Station Key Art', 'Official promotional key art for a PC space simulator launched on Steam.', 'concept-art', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=800&q=80', ARRAY['ComfyUI', 'SD3', 'Photoshop'], 'Multi-pass node generation followed by digital matte painting overpaint in Photoshop.', 'Lead Concept Artist', 'colossal ring-shaped orbital station orbiting a gas giant, cinematic lighting, hard sci-fi aesthetics', 'Full Entertainment IP Assignment with layered PSDs.'),
('c0000000-0000-0000-0000-000000000005', 'CleanGlow Skincare - Viral UGC Ad', 'Generated 3.2x ROAS in Meta paid traffic for a direct-to-consumer cosmetics startup.', 'video', 'https://images.unsplash.com/photo-1556228720-195a672e8a03?auto=format&fit=crop&w=800&q=80', ARRAY['HeyGen', 'ElevenLabs', 'CapCut'], 'HeyGen avatar paired with ElevenLabs voice synthesis and kinetic CapCut subtitles.', 'Producer & Hook Engineer', 'natural 20s woman in bathroom mirror talking enthusiastically about peptide serum, handheld camera wobble', 'Paid advertising clearance for Meta and TikTok Ads.'),
('c0000000-0000-0000-0000-000000000006', 'Chronicles of Kepler - Audio Drama', 'Produced full voice cast and generative ambient score for a 6-part episodic audio drama.', 'audio', 'https://images.unsplash.com/photo-1478737270239-2f02b77fc618?auto=format&fit=crop&w=800&q=80', ARRAY['ElevenLabs', 'Udio', 'Reaper'], 'Acoustic script analysis, multi-actor voice cloning, and Reaper broadcast LUFS mastering.', 'Sound Designer & Voice Director', 'deep resonant captain monologue, subtle spacesuit comms filter, ambient deep space hum', '100% royalty-free commercial audio buyout in perpetuity.'),
('c0000000-0000-0000-0000-000000000007', 'Botanica Serum - Hero Packshots', 'Hero listing images that boosted client Amazon conversion rate by 27%.', 'product', 'https://images.unsplash.com/photo-1608248597359-50937a00f28e?auto=format&fit=crop&w=800&q=80', ARRAY['Flux.1', 'ControlNet', 'Photoshop'], 'Zero-shot environment diffusion preserving exact packaging typography via ControlNet tile masks.', 'Packshot Designer', 'frosted glass serum dropper bottle resting on moss covered river stone, morning mist, water droplets', 'E-commerce and print commercial catalog rights.')
INSERT INTO public.projects (id, brand_id, title, description, business_objective, content_type, target_audience, creative_direction, required_skills, preferred_ai_tools, deliverables, dimensions_or_duration, deadline, optional_budget_min, optional_budget_max, budget_display, usage_platforms, commercial_use_requirements, status) VALUES
('p0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000001', 'Cinematic 15s AI Brand Film for Apex Volt Energy Drink', 'Looking for an experienced AI video director to produce a dynamic, high-octane 15-second vertical commercial. The concept features a neon-lit futuristic metropolis where characters gain electric energy after drinking Apex Volt. Need realistic motion, fluid simulations, and custom sound sync.', 'Drive 200k impressions on TikTok and establish cyberpunk brand identity.', 'AI Video', 'Gen-Z gamers, athletes, and creative professionals aged 18-28.', 'Fast camera zooms, neon electric blue and magenta accents, anamorphic motion blur, bass-heavy transitions.', ARRAY['Prompt Engineering', 'Camera Control', 'ControlNet', '4K Upscaling', 'Color Grading'], ARRAY['Runway Gen-3', 'Kling AI', 'Topaz Video AI'], ARRAY['1x 15s Hero Master (4K ProRes 422)', '3x 9:16 Social Cutdowns', 'Generation Seeds and Prompt Log'], '15 seconds (9:16 Vertical)', '14 days remaining', 1800, 2500, '$1,800 - $2,500', ARRAY['TikTok', 'Instagram Reels', 'YouTube Shorts'], ARRAY['Full Commercial Buyout', 'Perpetual IP Transfer', 'Paid Advertising Clearance'], 'Open'),
('p0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000001', 'AI Fashion Editorial Lookbook for Winter Minimalist Collection', 'Atelier Vesper is launching our Autumn/Winter knitwear line. We need 12 high-fashion editorial images featuring diverse models wearing structured oversized cashmere overcoats against Nordic fjord landscapes. Flawless fabric textures and natural human skin pores required for 300 DPI lookbook printing.', 'High-end brand editorial elevation and seasonal print lookbook release.', 'Generative Imagery', 'Affluent fashion consumers and boutique retail buyers.', 'Scandinavian minimalist, natural overcast daylight, rich cashmere weave details, muted earth tones.', ARRAY['Fabric Rendering', 'Skin Texture Realism', 'Editorial Lighting', 'High-Res Upscaling'], ARRAY['Midjourney v6', 'Magnific AI', 'Photoshop'], ARRAY['12x 300 DPI High-Res Print Masters', '12x 4:5 Instagram Feed Crops'], '300 DPI Print + Digital', '10 days remaining', 1200, 1600, '$1,200 - $1,600', ARRAY['Print Lookbook', 'Website Hero', 'Instagram'], ARRAY['Full Commercial Print Rights', 'Model Release Guarantee'], 'Open'),
('p0000000-0000-0000-0000-000000000003', 'b0000000-0000-0000-0000-000000000001', 'Synthetic Voiceover & Ambient Foley for Sci-Fi Audio Drama', 'We are producing a 5-episode audio drama exploring deep-space exploration. We need 3 distinct synthetic character voices (Ship AI, Commander, Android Engineer) plus custom ambient spaceship foley, engine hums, and spatial audio mastering.', 'Produce captivating audio entertainment with zero guild actor licensing delays.', 'Voice & Audio', 'Sci-fi fans, narrative podcast listeners.', 'Immersive cinematic audio bed, realistic cockpit intercom acoustics, binaural spatial depth.', ARRAY['Voice Modulation', 'Emotion Prompting', 'Audio Mastering', 'Foley AI Synthesis'], ARRAY['ElevenLabs Pro', 'Suno v3.5', 'Reaper DAW'], ARRAY['5x 20-minute Audio Episodes (24-bit 48kHz WAV)', 'Isolated Voice & Music Stems'], '5 Episodes x 20 mins', '21 days remaining', 2200, 3000, '$2,200 - $3,000', ARRAY['Spotify', 'Apple Podcasts', 'YouTube Audio'], ARRAY['Perpetual Worldwide Audio Buyout'], 'Open'),
('p0000000-0000-0000-0000-000000000004', 'b0000000-0000-0000-0000-000000000001', 'Photorealistic Zero-Shot Product Packshots for Organic Botanical Teas', 'Need 8 premium staged product images for our new organic loose-leaf tea tins. Must preserve our exact logo typography and packaging label while placing the tin on handcrafted ceramic saucers with dried chamomile flowers, honey drippers, and soft morning steam.', 'Amazon Brand Store launch and social ad conversions.', 'Product Staging', 'Health-conscious wellness tea drinkers.', 'Warm morning sunlight, organic textures, steam swirl simulation, zero label distortion.', ARRAY['Logo Preservation', 'ControlNet Tile', 'Reflection Mapping', 'Packshot Staging'], ARRAY['Flux.1', 'ControlNet', 'Photoshop CC'], ARRAY['8x E-Commerce Hero Images (2000x2000 px)', 'Raw PSD layers with masks'], '2000x2000 E-Commerce', '7 days remaining', 800, 1100, '$800 - $1,100', ARRAY['Shopify', 'Amazon Store', 'Pinterest'], ARRAY['Commercial E-Commerce Rights', 'Logo Preservation Warranty'], 'Open'),
('p0000000-0000-0000-0000-000000000005', 'b0000000-0000-0000-0000-000000000001', 'Persistent Virtual Influencer Ambassador for Streetwear Label', 'Develop a synthetic brand ambassador with consistent facial features across 20 seasonal campaign looks. Train custom LoRA models and supply generation seeds for continuous brand usage.', 'Build an iconic owned virtual IP to anchor long-term influencer campaigns.', 'Virtual Influencer', 'Streetwear & sneakerheads aged 16-30.', 'Edgy Tokyo street fashion, natural skin micro-texture, authentic candid smartphone poses.', ARRAY['LoRA Fine-Tuning', 'Flux.1 Control', 'Blender 4.2', 'Identity Lock'], ARRAY['Flux.1 Dev', 'InstantID', 'ComfyUI'], ARRAY['Trained LoRA Weights (.safetensors)', '20x High-Res Editorial Looks', 'Workflow Guide'], 'High-Res Multi-Angle Renders', '25 days remaining', 2500, 3500, '$2,500 - $3,500', ARRAY['Instagram', 'TikTok', 'Digital Billboard'], ARRAY['Exclusive Virtual IP Transfer', 'Source LoRA Weights Delivery'], 'Open')
INSERT INTO public.applications (project_id, creator_id, proposal, estimated_delivery_time, optional_proposed_price, status) VALUES
('p0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000001', 'Hi Apex Volt team! I''ve directed over 40 AI video commercials using Runway Gen-3 and Kling AI. The energy drink concept fits right into my cyberpunk aesthetic. I can deliver 3 camera cut variations, custom sound design, and 4K ProRes masters within 8 days.', '8 days', '$2,100', 'Submitted'),
('p0000000-0000-0000-0000-000000000001', 'c0000000-0000-0000-0000-000000000005', 'We specialize in viral 9:16 vertical ads specifically optimized for TikTok retention curves. I''d love to generate UGC style action shots paired with dynamic captions and sound.', '6 days', '$1,850', 'Under Review'),
('p0000000-0000-0000-0000-000000000002', 'c0000000-0000-0000-0000-000000000003', 'This brief aligns seamlessly with my work for European fashion ateliers. I use Midjourney v6 + Magnific AI to ensure textile weaves and cashmere fibers look indistinguishable from real photography at 300 DPI.', '5 days', '$1,450', 'Accepted')
